solution.code:
export const plan = {
  cartera: "empresa de ejemplo",
  aplicaciones: [
    { nombre: "Servidores de oficina trasladados sin cambios", estrategia: "REHOST" },
    { nombre: "Instancia RDS que pasa a otra cuenta de AWS sin cambios", estrategia: "RELOCATE" },
    { nombre: "CRM con licencia sustituido por la versión SaaS del proveedor", estrategia: "REPURCHASE" },
    { nombre: "Aplicación sin uso que se apaga", estrategia: "RETIRE" },
    { nombre: "Aplicación con hardware especializado sin equivalente en la nube", estrategia: "RETAIN" },
    { nombre: "Monolito rediseñado con funciones nativas de la nube", estrategia: "REFACTOR" },
  ],
};

spec.code:
const app = plan.aplicaciones.find((a) => a.nombre === "Instancia RDS que pasa a otra cuenta de AWS sin cambios");
assert.ok(app, "debe existir la aplicación de la instancia RDS");
assert.strictEqual(app.estrategia, "RELOCATE");

const siete = ["RETIRE", "RETAIN", "REHOST", "RELOCATE", "REPURCHASE", "REPLATFORM", "REFACTOR"];
for (const app of plan.aplicaciones) {
  assert.ok(siete.includes(app.estrategia), app.nombre + " usa una estrategia desconocida");
}

const esperado = {
  "Servidores de oficina trasladados sin cambios": "REHOST",
  "CRM con licencia sustituido por la versión SaaS del proveedor": "REPURCHASE",
  "Aplicación sin uso que se apaga": "RETIRE",
  "Aplicación con hardware especializado sin equivalente en la nube": "RETAIN",
  "Monolito rediseñado con funciones nativas de la nube": "REFACTOR",
};
for (const [nombre, estrategia] of Object.entries(esperado)) {
  const app = plan.aplicaciones.find((a) => a.nombre === nombre);
  assert.ok(app, "falta la aplicación " + nombre);
  assert.strictEqual(app.estrategia, estrategia);
}

