// Decide si una estrategia es de uso común en una migración grande. Corrige su defecto principal.
export const COMUNES = ["REHOST", "REPLATFORM", "RELOCATE", "REFACTOR"];

export function esComunEnMigracionGrande(estrategia: string): boolean {
  return COMUNES.includes(estrategia);
}

